WITH recent_shipments AS (SELECT * FROM shipments WHERE delivered_date > '2023-06-04' AND delivered_date > '2025-01-01' AND cost < 93), shipments_stats AS (SELECT CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END AS delivered_cohort, CASE WHEN cost >= 88 THEN 'high' WHEN cost >= 43 THEN 'mid' ELSE 'low' END AS cost_bucket, MIN(cost) AS min_cost FROM recent_shipments GROUP BY CASE WHEN YEAR(delivered_date) < 2024 THEN 'before_2024' WHEN YEAR(delivered_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN cost >= 88 THEN 'high' WHEN cost >= 43 THEN 'mid' ELSE 'low' END) SELECT * FROM shipments_stats
